catalog.push(...Content.assets);
const byId=Object.fromEntries(catalog.map(a=>[a.id,a]));
function body(id,p){const a=byId[id];if(!a||!a.body)return '';return a.body.replace(/@([a-z]+)/g,(_,key)=>key==='roof'?p.roof[1]:(p[key]||p.ink));}
return {catalog,byId,body,categories:[...new Set(catalog.map(a=>a.category))]};
